mapper.select:
SELECT COALESCE(SUM(order_total), 0)
FROM mis_sales_order
WHERE finance_approve_status = '1'
  AND del_flag = '0'
  AND create_time >= #{start}
  AND create_time <= #{end}

SELECT po.id, po.offer_no as offerNo, po.customer_name as customerName, c.customer_type as customerType, po.offer_date as offerDate, po.create_time as createTime FROM mis_price_offer po LEFT JOIN mis_customer c ON po.customer_id = c.id WHERE po.approve_status = '0' AND po.del_flag = '0'
AND po.salesman_id = #{salesmanId}
ORDER BY po.create_time DESC LIMIT 10

SELECT so.id, so.order_no as orderNo, so.customer_name as customerName, so.order_total as orderTotal, so.order_date as orderDate, so.finance_approve_status as financeApproveStatus, so.sales_approve_status as salesApproveStatus, so.delivery_date as deliveryDate FROM mis_sales_order so WHERE (so.finance_approve_status = '0' OR so.sales_approve_status = '0') AND so.del_flag = '0'
AND so.salesman_id = #{salesmanId}
ORDER BY so.create_time DESC LIMIT 10

SELECT so.id, so.order_no as orderNo, so.customer_name as customerName, so.order_total as orderTotal, so.delivery_date as deliveryDate, COALESCE(SUM(sod.order_qty - sod.delivery_qty), 0) as remainQty FROM mis_sales_order so LEFT JOIN mis_sales_order_detail sod ON so.id = sod.order_id WHERE so.finance_approve_status = '1' AND so.del_flag = '0' AND sod.del_flag = '0' AND sod.delivery_qty < sod.order_qty
AND so.salesman_id = #{salesmanId}
GROUP BY so.id, so.order_no, so.customer_name, so.order_total, so.delivery_date ORDER BY so.delivery_date ASC LIMIT 10

SELECT so.id, so.order_no as orderNo, so.customer_name as customerName, so.order_total as orderTotal, so.delivery_date as deliveryDate, DATEDIFF(so.delivery_date, CURDATE()) as daysRemain, COALESCE(SUM(sod.order_qty - sod.delivery_qty), 0) as remainQty FROM mis_sales_order so LEFT JOIN mis_sales_order_detail sod ON so.id = sod.order_id WHERE so.finance_approve_status = '1' AND so.del_flag = '0' AND sod.del_flag = '0' AND so.delivery_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY) AND sod.delivery_qty < sod.order_qty
AND so.salesman_id = #{salesmanId}
GROUP BY so.id, so.order_no, so.customer_name, so.order_total, so.delivery_date ORDER BY so.delivery_date ASC LIMIT 10

SELECT spp.id, spp.plan_no as planNo, spp.sales_order_no as salesOrderNo, c.customer_name as customerName, spp.plan_amount as planAmount, spp.paid_amount as paidAmount, spp.unpaid_amount as unpaidAmount, spp.plan_date as planDate, spp.plan_stage as planStage FROM mis_sales_payment_plan spp LEFT JOIN mis_sales_order so ON spp.sales_order_id = so.id LEFT JOIN mis_customer c ON spp.customer_id = c.id WHERE spp.unpaid_amount > 0 AND spp.del_flag = '0' AND DATE_FORMAT(spp.plan_date, '%Y-%m') = DATE_FORMAT(NOW(), '%Y-%m')
AND spp.salesman_id = #{salesmanId}
ORDER BY spp.plan_date ASC LIMIT 10

SELECT DATE_FORMAT(m.order_date, '%Y-%m') as month, COALESCE(SUM(m.order_total), 0) as amount, COUNT(*) as orderCount, COALESCE(SUM(d.receipt_amount), 0) as receiptAmount FROM mis_sales_order m LEFT JOIN ( SELECT sales_order_id, SUM(receipt_amount) as receipt_amount FROM mis_receipt_order_detail WHERE del_flag = '0' GROUP BY sales_order_id ) d ON m.id = d.sales_order_id WHERE m.order_date >= DATE_SUB(DATE_FORMAT(NOW(), '%Y-%m-01'), INTERVAL 11 MONTH) AND m.finance_approve_status = '1' AND m.del_flag = '0'
AND m.salesman_id = #{salesmanId}
GROUP BY DATE_FORMAT(m.order_date, '%Y-%m') ORDER BY month ASC

SELECT customer_type as customerType, COUNT(*) as customerCount FROM mis_customer WHERE del_flag = '0'
AND salesman_id = #{salesmanId}
GROUP BY customer_type ORDER BY customerCount DESC
